CREATE OR REPLACE FUNCTION public.notification_snippet(p_text text, p_max integer DEFAULT 60)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  with first_line as (
    select trim(regexp_replace(
             regexp_replace(
               coalesce((select l from regexp_split_to_table(coalesce(p_text, ''), E'\\r?\\n') as l
                          where trim(l) <> '' limit 1), ''),
               '^\s*(#{1,6}\s+|>\s*|[-*]\s+)', ''),
             '(\*\*|__|\*|~~|`)', '', 'g')) as s
